17	import java.util.function.Function;
18	import java.util.stream.Collectors;
19	
20	@Service
21	@Transactional(readOnly = true)
22	public class ListActiveLoansService implements ListActiveLoansUseCase {
23	
24	    private final LoadMemberPort loadMemberPort;
25	    private final LoadLoanPort loadLoanPort;
26	    private final LoadBookPort loadBookPort;
27	
28	    public ListActiveLoansService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort) {
29	        this.loadMemberPort = loadMemberPort;
30	        this.loadLoanPort = loadLoanPort;
31	        this.loadBookPort = loadBookPort;
32	    }
33	
34	    @Override
35	    public ActiveLoanPage listActiveLoans(ListActiveLoansQuery query) {
36	        UUID memberId = query.memberId();
37	        loadMemberPort.loadMember(memberId).orElseThrow(() -> new MemberNotFoundException(memberId));
38	
39	        long totalCount = loadLoanPort.countActiveLoansByMemberId(memberId);
40	        List<Loan> loans = loadLoanPort.loadActiveLoansByMemberId(memberId, query.page(), query.size());
41	        Map<UUID, String> titles = titlesByBookId(loans);
42	
43	        List<ActiveLoan> items = loans.stream()
44	                .map(loan -> new ActiveLoan(loan.getId(), loan.getBookId(), titles.get(loan.getBookId()),
45	                        loan.getLoanedAt(), loan.getDueAt()))
46	                .toList();
47	        return new ActiveLoanPage(items, query.page(), query.size(), totalCount);
48	    }
49	
50	    private Map<UUID, String> titlesByBookId(List<Loan> loans) {
51	        List<UUID> bookIds = loans.stream().map(Loan::getBookId).distinct().toList();
52	        Map<UUID, Book> booksById = loadBookPort.loadBooks(bookIds).stream()
53	                .collect(Collectors.toMap(Book::getId, Function.identity()));
54	        return bookIds.stream().collect(Collectors.toMap(Function.identity(), bookId -> {
55	            Book book = booksById.get(bookId);
56	            if (book == null) {
57	                throw new BookNotFoundException(bookId);
58	            }
59	            return book.getTitle();
60	        }));
61	    }
62	}
